// Education only. Reading or dismissing this guide never grants a permission.
export const introKey='cctv.prototype.privacy-intro.v1';
let seenInSession=false;
export function shouldShowPrivacyIntro(path){if(path!=='home')return false;try{if(localStorage.getItem(introKey)==='seen')return false;}catch{}return !seenInSession;}
export function dismissPrivacyIntro(){seenInSession=true;try{localStorage.setItem(introKey,'seen');}catch{}}
const sources={policy:'https://www.eufy.com/au/policies/privacy-policy',terms:'https://www.eufy.com/au/policies/terms-of-service',storage:'https://service.eufy.com/article-description/Indoor-Cam-E30-How-Do-I-Store-Video-Recordings-on-My-Camera',product:'https://www.eufy.com/au/products/indoor-cam-e30?variant=51775675367791',manage:'https://service.eufy.com/article-description/How-to-Clear-Storage-on-eufy-Device',support:'https://service.eufy.com/au'};
const link=(key,label)=>`<a class="privacy-source" href="${sources[key]}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
const icons={journey:'<rect x="3" y="5" width="7" height="7" rx="2"/><rect x="14" y="12" width="7" height="7" rx="2"/><path d="M10 8h7v4M7 12v5h7"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M17 5a3 3 0 0 1 0 6m1 3q4 1 4 7"/>',copies:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M15 8V3H3v12h5"/>',shield:'<path d="m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6z"/><path d="m8 12 3 3 5-6"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]}</svg>`;
const topics=[['data-journey','journey','Your data journey','What is collected, how it travels, and where it is saved.'],['people-access','people','People & access','Who can view your camera and how access is checked.'],['keep-share-delete','copies','Keep, share or delete','How long recordings stay and what happens to copies.']];
const question=(title,body)=>`<details class="privacy-question"><summary>${title}<span aria-hidden="true">+</span></summary><div class="privacy-answer">${body}</div></details>`;
const header=(title,copy,back='#privacy',backLabel='Privacy')=>`<nav class="privacy-breadcrumb"><a href="${back}">← ${backLabel}</a><span>Indoor Cam E30</span></nav><header class="privacy-page-header"><span class="privacy-eyebrow">PRIVACY, EXPLAINED</span><h1 tabindex="-1">${title}</h1><p>${copy}</p></header>`;
const exampleNote='<span class="privacy-example">Example setup</span><p class="privacy-context">An illustration of an E30 setup, not a reading of your camera’s current settings.</p>';
function landing(){return `<div class="privacy-landing privacy-original"><div class="ob-hub-head"><div class="ob-hub-brand">${icon('shield')}<span>eufy<small>PRIVACY, EXPLAINED</small></span></div><button class="privacy-skip" data-privacy-dismiss>Skip for now</button></div><div class="ob-hub-layout"><div class="ob-hub-intro"><span class="ob-hub-label">INDOOR CAM E30</span><h1 tabindex="-1">Your privacy choices,<em>made clear.</em></h1><p class="ob-lead">Follow the connected path to understand where your data goes, who can view it, and what happens to your recordings.</p><p class="privacy-read-note">Explore in any order. No confirmations needed.</p><div class="ob-hub-picture" aria-hidden="true"><span>${icon('journey')}Your data journey<small>Understand the path, one step at a time</small></span><div><i>${icon('journey')}</i><b>→</b><i>${icon('shield')}</i><b>→</b><i>${icon('copies')}</i></div></div><div class="privacy-landing-actions"><button class="eufy-primary" data-privacy-dismiss>Continue to Home</button></div><a class="privacy-basics-link" href="#privacy/basics">${icon('shield')}Privacy settings & policies <span>→</span></a><p class="privacy-fine-print">Continuing or skipping does not accept terms or change permissions.<br>Reopen this guide in Settings → Privacy.</p></div><div class="ob-flow-region privacy-connected" aria-label="Three privacy topics connected by a path"><svg class="ob-flow-lines" viewBox="0 0 600 530" preserveAspectRatio="none" aria-hidden="true"><path class="privacy-path-base" d="M390 132 V174 Q390 190 370 190 H210 Q190 190 190 210 V240 M190 302 V344 Q190 360 210 360 H370 Q390 360 390 380 V410"/><path class="privacy-path-moving" d="M390 132 V174 Q390 190 370 190 H210 Q190 190 190 210 V240 M190 302 V344 Q190 360 210 360 H370 Q390 360 390 380 V410"/></svg>${topics.map(([path,symbol,title,copy],i)=>`<a href="#privacy/${path}" class="ob-flow-node ${i%2?'left':'right'} ${i===2?'final':''}" style="--node-top:${50+i*170}px;--entry-delay:${i*140}ms"><span class="ob-node-index">0${i+1}</span><span class="ob-node-icon">${icon(symbol)}</span><span class="ob-node-copy"><small>${['Follow your data','Understand access','Manage your copies'][i]}</small><strong>${title}</strong><span>${copy}</span></span><span class="ob-node-chevron" aria-hidden="true">›</span></a>`).join('')}</div></div><div class="privacy-policy-footer">${link('policy','Privacy Notice')}${link('terms','Terms of Use')}<a href="#settings">Settings</a></div></div>`;}

const nodes={camera:{title:'1. Camera — collection',body:'The E30 captures the scene in front of its lens. Recordings can include video and sound when audio recording is enabled. Event clips and continuous recording are different recording modes; what is saved depends on the setup. This prototype captures neither real video nor sound.'},storage:{title:'2. microSD card — local storage',body:'In this example, recordings are saved on a microSD card inside the camera. The card is a physical storage location in your home. Storage capacity and recording mode affect how much footage it can hold.'},app:{title:'3. eufy app — viewing',body:'The app lets an authorised account view live or saved footage. Viewing is different from downloading: downloading creates a separate copy on the destination device. Local recordings can still be viewed remotely through the app.'}};
function journey(){return `${header('Your data journey','Follow a recording from the camera to its storage location and the app.')}<section class="privacy-surface">${exampleNote}<div class="privacy-route" aria-label="Recording storage and viewing path"><button class="privacy-node" data-data-node="camera" aria-pressed="true" aria-controls="privacy-node-detail"><span class="privacy-node-symbol">${icon('journey')}</span><strong>Camera</strong><small>Collects</small></button><span class="privacy-arrow" aria-hidden="true">→</span><button class="privacy-node" data-data-node="storage" aria-pressed="false" aria-controls="privacy-node-detail"><span class="privacy-node-symbol">▤</span><strong>microSD card</strong><small>Saves locally</small></button><span class="privacy-arrow" aria-hidden="true">→</span><button class="privacy-node" data-data-node="app" aria-pressed="false" aria-controls="privacy-node-detail"><span class="privacy-node-symbol">▯</span><strong>eufy app</strong><small>Views recordings</small></button></div><p class="privacy-route-caption">Recording and viewing flow · arrows do not represent a complete network diagram.</p><div id="privacy-node-detail" class="privacy-node-detail" role="region" aria-live="polite"><h2>${nodes.camera.title}</h2><p>${nodes.camera.body}</p></div>${question('See the optional cloud backup path','<div class="privacy-mini-flow"><span>Camera recordings</span><b>→</b><span>eufy Cloud backup</span><b>→</b><span>View in the app</span></div><p>Cloud backup adds a cloud storage location when it is enabled with a supported subscription. It is not shown as active in this example. It should not be confused with the local microSD copy.</p>'+link('storage','E30 storage options'))}${question('What if I use HomeBase?','<p>HomeBase is another supported local-storage configuration for E30. It stores footage on the HomeBase rather than the microSD setup illustrated above. Check your actual device configuration in the eufy app; this prototype does not detect a connected HomeBase.</p>'+link('product','E30 compatibility information'))}</section><section class="privacy-knowledge"><h2>Good to know</h2>${question('Wi-Fi connects devices. It is not a storage location.','<p>Wi-Fi is a way to transfer data. A microSD card, HomeBase or cloud service is where a recording may be saved. Connecting to Wi-Fi does not, by itself, tell you which storage option is in use.</p>')}${question('Remote viewing does not necessarily mean cloud storage.','<p>E30 local recordings can be viewed remotely in the app. The location where you watch a recording and the location where it is stored are different things.</p>'+link('storage','How E30 stores recordings'))}${question('A notification preview can take a different path.','<p>Optional notifications with thumbnail previews may require a thumbnail image to be temporarily stored in the cloud, even when video recordings are stored locally. Text-only notifications and video backups are separate features.</p>'+link('product','Official cloud-feature notes'))}</section><a class="privacy-next" href="#privacy/people-access">Next: People & access →</a>`;}
function people(){return `${header('People & access','Knowing who can view a camera is different from knowing who appears in a recording.')}<section class="privacy-surface"><h2>Access belongs to an account</h2><p class="privacy-section-copy">This example uses the members and camera permissions in your prototype.</p><div class="privacy-people"><article><span>AL</span><div><strong>Alex (You)</strong><small>Owner · Both cameras</small></div></article><article><span>EM</span><div><strong>Emma</strong><small>Family member · Living Room</small></div><a href="#events/permissions/emma">Review access →</a></article><article><span>JA</span><div><strong>James</strong><small>Guest · Front Door</small></div><a href="#events/permissions/james">Review access →</a></article></div>${question('Live video and saved recordings are different types of access.','<p>Live video shows the current camera view. Saved recordings show footage recorded earlier. Review which cameras and types of viewing a shared account is permitted to use; do not assume that sharing one camera gives access to every device.</p>')}${question('What do the viewing-permission choices mean?','<p>In this prototype you can preview Original view, Hide faces, Hide whole person and No access. They describe what a member should be able to see in future access. Changing a setting does not rewrite the access history.</p>')}<a class="eufy-primary privacy-inline-action" href="#events/access">Open Access History</a></section><section class="privacy-surface"><div class="privacy-section-heading"><h2>Face verification checks the viewer</h2><span class="privacy-example">Prototype demo</span></div><div class="privacy-mini-flow"><span>Face verification</span><b>+</b><span>Camera permission</span><b>→</b><span>Allow or deny</span></div><p class="privacy-section-copy">A matching face must not grant access to a camera the account is not permitted to view. This refers to the person trying to open the camera, not someone seen in its footage.</p><p class="privacy-callout">The current verification demo uses a selected example identity. It does not activate a camera, compare real faces, or collect photographs, face templates or other biometric data.</p><a href="#verify/living-room" class="eufy-secondary privacy-inline-action">Try the Verification Demo</a></section><a class="privacy-next" href="#privacy/keep-share-delete">Next: Keep, share or delete →</a>`;}
function copies(){return `${header('Keep, share or delete','A recording can have more than one copy. Manage each storage location separately.')}<section class="privacy-surface"><h2>How long does a recording stay?</h2><p class="privacy-section-copy">There is no single retention time for every setup. Available storage capacity, recording mode and any cloud plan affect how long recordings are kept. This prototype cannot read your actual retention settings.</p>${question('What should I check in the real app?','<p>Check the selected camera’s storage location, available space and recording mode. For cloud backup, check the terms of the plan in use. Do not treat a recording remaining on your phone as proof that the original is still on the camera.</p>'+link('storage','Review E30 storage options'))}</section><section class="privacy-surface"><h2>Watch, download and share</h2><div class="privacy-copy-map"><div><strong>Saved recording</strong><small>microSD / HomeBase / cloud, depending on setup</small></div><span aria-hidden="true">↓</span><div><strong>Download a copy</strong><small>A separate file on your phone or computer</small></div><span aria-hidden="true">↓</span><div><strong>Share the file</strong><small>The recipient may have another copy</small></div></div>${question('Does viewing save a permanent copy on my phone?','<p>Viewing and deliberately downloading a recording are different actions. A downloaded or exported file is a separate copy that needs to be managed on the destination device. An app may also use temporary data; do not confuse that with a downloaded recording.</p>')}${question('Is sharing camera access the same as sharing a file?','<p>No. Camera sharing gives an account a permission to use the app. Sharing an exported file sends a separate copy. Revoking an account’s future camera access should not be presented as deleting a file someone has already downloaded.</p>')}</section><section class="privacy-surface"><h2>Before deleting, check the location</h2><ul class="privacy-checklist"><li><strong>Local recording:</strong> manage the copy on the selected camera or HomeBase.</li><li><strong>Cloud backup:</strong> manage any separate cloud copy through the relevant service.</li><li><strong>Downloaded or shared file:</strong> manage that copy on the destination device or with its recipient.</li></ul><p class="privacy-callout">Do not assume one delete action removes every copy. Formatting local storage is a destructive action; review what the real app says will be erased before using it.</p>${link('manage','Official storage-management instructions')}${link('policy','Official privacy and data-rights information')}<p class="privacy-fine-print">This guide explains the options. It does not delete recordings, format storage, or submit a data request.</p></section><a href="#privacy/basics" class="privacy-next">Privacy settings & policies →</a>`;}
function basics(){return `${header('Privacy settings & policies','The essentials, alongside your three privacy guides.')}<section class="privacy-surface"><h2>Official documents</h2><p class="privacy-section-copy">These links open the official eufy documents in a new tab. This coursework prototype does not replace those documents or accept them for you.</p><div class="privacy-document-links">${link('policy','Privacy Notice')}${link('terms','Terms of Use')}</div></section><section class="privacy-knowledge"><h2>App Permissions</h2><p class="privacy-section-copy">Real permission status has not been checked. Manage permissions in your browser or device settings.</p>${question('Camera & microphone','<p>Camera permission can allow a site or app to use your device’s camera. Microphone permission can allow it to capture sound. These permissions are separate from a security camera’s own recording settings.</p><p>The face-verification demo here does not request either permission and does not capture a real face.</p>')}${question('Notifications & important alerts','<p>Notification permissions control whether an app can deliver notifications. Important alerts and thumbnail previews may have additional settings. A saved preference inside this prototype is not proof of an operating-system permission.</p><a class="privacy-source" href="#notifications">View demo notification preferences →</a>')}${question('Network access','<p>A network connection transfers data. It is not consent to every kind of data use and does not identify the storage location. This website cannot read or change an operating-system Wi-Fi/mobile-data permission.</p>')}</section><section class="privacy-knowledge"><h2>Your Data & Rights</h2>${question('Access, download or request deletion of real eufy data','<p>Use the real eufy app and official account channels to manage recordings and copies. The official Privacy Notice explains relevant data rights and how to contact eufy about a request.</p><p>No request is submitted by reading this guide.</p>'+link('policy','Read the official Privacy Notice')+link('support','Contact eufy support'))}${question('What does this prototype store in my browser?','<p>The prototype may store demonstration viewing permissions, simulated face-verification events, notification preferences from the earlier flow, and whether you have dismissed this introduction.</p><p>It does not store real camera footage or face biometrics. The records stay in this browser; the local-storage data is not sent by this guide to eufy or a new analytics service.</p>')}${question('What does Continue or Skip mean?','<p>Either button closes the educational introduction. It does not accept a contract, grant permission, enable analytics or change who can view your cameras. You can return through Settings → Privacy at any time.</p>')}</section>`;}
export function privacyView(app,topic=''){
 app.className='native-page privacy-page';document.title='eufy · Privacy';
 const views={'data-journey':journey,'people-access':people,'keep-share-delete':copies,basics};
 app.innerHTML=topic?(views[topic]||landing)():landing();
 app.querySelectorAll('[data-privacy-dismiss]').forEach(button=>button.onclick=()=>{dismissPrivacyIntro();location.hash='home';});
 app.querySelectorAll('[data-data-node]').forEach(button=>button.onclick=()=>{const node=nodes[button.dataset.dataNode];app.querySelectorAll('[data-data-node]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));app.querySelector('#privacy-node-detail').innerHTML=`<h2>${node.title}</h2><p>${node.body}</p>`;});
}
export function settingsView(app){app.className='native-page privacy-page';document.title='eufy · Settings';app.innerHTML=`${header('Settings','Your prototype preferences and privacy information.','#home','Home')}<section class="privacy-surface privacy-settings-list"><a href="#privacy"><span class="privacy-topic-icon">${icon('shield')}</span><span><strong>Privacy</strong><small>Your data journey, people & access, keep, share or delete</small></span><b>›</b></a><a href="#privacy/basics"><span class="privacy-topic-icon">${icon('copies')}</span><span><strong>Privacy settings & policies</strong><small>Official documents, app permissions and your data rights</small></span><b>›</b></a><a href="#notifications"><span class="privacy-topic-icon">${icon('people')}</span><span><strong>Notifications</strong><small>Prototype notification preferences</small></span><b>›</b></a></section>`;}
